<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';
$cart=$_SESSION['cart']??[];if(!$cart){flash('error','Shporta është bosh.');redirect('cart.php');}
$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$stmt=$db->prepare("SELECT * FROM products WHERE id IN ($in) AND is_active=1");$types=str_repeat('i',count($ids));$stmt->bind_param($types,...$ids);$stmt->execute();$result=$stmt->get_result();$items=[];$subtotal=0;while($p=$result->fetch_assoc()){$p['qty']=$cart[$p['id']];$subtotal+=$p['price']*$p['qty'];$items[]=$p;}$total=$subtotal+($subtotal>=100?0:3);
$errors=[];$name=$_SESSION['user']['name']??'';$email=$_SESSION['user']['email']??'';$phone='';$address='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(strlen($name)<2)$errors[]='Shkruani emrin.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Email jo valid.';if(strlen($phone)<6)$errors[]='Shkruani telefonin.';if(strlen($address)<8)$errors[]='Shkruani adresën e plotë.';foreach($items as $p)if($p['qty']>$p['stock'])$errors[]=$p['name'].' nuk ka stok të mjaftueshëm.';
if(!$errors){$db->begin_transaction();try{$userId=$_SESSION['user']['id']??null;$order=$db->prepare("INSERT INTO orders(user_id,customer_name,email,phone,address,total,status) VALUES(?,?,?,?,?,?,'pending')");$order->bind_param('issssd',$userId,$name,$email,$phone,$address,$total);$order->execute();$orderId=$db->insert_id;$line=$db->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,price) VALUES(?,?,?,?,?)');$stock=$db->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');foreach($items as $p){$line->bind_param('iisid',$orderId,$p['id'],$p['name'],$p['qty'],$p['price']);$line->execute();$stock->bind_param('iii',$p['qty'],$p['id'],$p['qty']);$stock->execute();if(!$stock->affected_rows)throw new Exception('Stoku ndryshoi.');}$db->commit();unset($_SESSION['cart']);flash('success','Porosia #'.$orderId.' u pranua me sukses!');redirect(is_logged_in()?'account.php':'index.php');}catch(Throwable $e){$db->rollback();$errors[]='Porosia nuk u ruajt. Ju lutem provoni përsëri.';}}}
$pageTitle='Përfundo porosinë';require __DIR__.'/includes/header.php';
?>
<section class="cart-section"><div class="container"><p class="eyebrow">Hapi i fundit</p><h1>Përfundo porosinë</h1><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="cart-layout"><div class="contact-form"><?php if($errors): ?><div class="error-list"><?php foreach($errors as $error): ?><div>• <?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><div class="form-group"><label>Emri i plotë</label><input name="name" value="<?= e($name) ?>" required></div><div class="form-group"><label>Email</label><input type="email" name="email" value="<?= e($email) ?>" required></div><div class="form-group"><label>Telefoni</label><input name="phone" value="<?= e($phone) ?>" required></div><div class="form-group"><label>Adresa e dërgesës</label><textarea name="address" required><?= e($address) ?></textarea></div><p class="muted">Pagesa bëhet me para në dorëzim.</p></div><aside class="summary-card"><h3>Porosia</h3><?php foreach($items as $item): ?><div class="summary-row"><span><?= e($item['name']) ?> × <?= $item['qty'] ?></span><strong><?= money($item['price']*$item['qty']) ?></strong></div><?php endforeach; ?><div class="summary-row summary-total"><span>Totali</span><span><?= money($total) ?></span></div><button class="button button-dark" style="width:100%;margin-top:20px">Konfirmo porosinë</button></aside></div></form></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
